import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    points = [(data[i + 1], data[i + 2]) for i in range(1, 2 * n, 2)]

    comparable = [0] * n
    for i in range(n):
        xi, yi = points[i]
        mask = 0
        for j in range(n):
            if i == j:
                continue
            xj, yj = points[j]
            if (xj < xi and yj < yi) or (xj > xi and yj > yi):
                mask |= 1 << j
        comparable[i] = mask

    initial = (1 << n) - 1
    seen = {initial}
    stack = [initial]
    while stack:
        state = stack.pop()
        remaining = state
        while remaining:
            bit = remaining & -remaining
            k = bit.bit_length() - 1
            remaining -= bit
            nxt = state & ~comparable[k]
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    print(len(seen) % MOD)

if __name__ == '__main__':
    main()

