def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]
    limit = max(a, default=1)
    spf = list(range(limit + 1))
    for p in range(2, int(limit**0.5) + 1):
        if spf[p] == p:
            for x in range(p*p, limit+1, p):
                if spf[x] == x:
                    spf[x] = p
    nim = 0
    for x in a:
        cnt = 0
        while x > 1:
            x //= spf[x]
            cnt += 1
        nim ^= cnt
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

