from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        mx = second = count = 0
        max_id = -1
        base = 0
        gain = [0] * len(conflictingPairs)
        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > mx:
                    second = mx
                    mx = a
                    count = 1
                    max_id = idx
                elif a == mx:
                    count += 1
                elif a > second:
                    second = a
            base += r - mx
            if count == 1 and max_id >= 0:
                gain[max_id] += mx - second
        return base + max(gain, default=0)

