import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a - 1, b - 1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            idx = z[1] - 1
            closed[idx] = True
            queries.append((1, idx))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))
    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = d[b][a] = c
    for k in range(N):
        dk = d[k]
        for i in range(N):
            row = d[i]
            dik = row[k]
            if dik < INF:
                row[:] = [min(row[j], dik + dk[j]) for j in range(N)]
    ans = []
    for q in reversed(queries):
        if q[0] == 2:
            val = d[q[1]][q[2]]
            ans.append(str(val if val < INF else -1))
        else:
            u, v, w = edges[q[1]]
            du = [d[i][u] for i in range(N)]
            dv = [d[i][v] for i in range(N)]
            for i in range(N):
                row = d[i]
                x = du[i] + w
                y = dv[i] + w
                row[:] = [min(row[j], x + dv[j], y + du[j]) for j in range(N)]
    print('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

