class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Number of popcount iterations needed to reach one.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]
        valid = [False] * (n + 1)
        for t in range(1, n + 1):
            valid[t] = steps[t] + 1 <= k

        # Pascal triangle for all needed binomial coefficients.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for t in range(1, n + 1):
                    if valid[t]:
                        need = t - ones
                        if 0 <= need <= rem:
                            ans += comb[rem][need]
                ones += 1
        return ans % MOD

