import sys
sys.setrecursionlimit(1_000_000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = []
    for _ in range(M):
        s, t = next(it), next(it)
        people.append((min(s, t)-1, max(s, t)-1, s < t))
    queries = [(next(it), next(it)) for _ in range(Q)]
    out = []
    for L, R in queries:
        # Vertices 0..N-1 represent town potentials. Equal endpoint values
        # are represented by opposing non-strict edges; interval inequalities
        # are represented by strict directed edges through a segment tree.
        # This direct construction is intended for the given query interval.
        base = 1
        while base < N:
            base <<= 1
        total = N + 2*base
        adj = [[] for _ in range(total)]
        radj = [[] for _ in range(total)]
        strict_edges = []
        def edge(a, b, strict=False):
            adj[a].append(b)
            radj[b].append(a)
            if strict:
                strict_edges.append((a, b))
        def cover(l, r, src, forward):
            # half-open range of town vertices
            l += base
            r += base
            while l < r:
                if l & 1:
                    if forward: edge(src, l)
                    else: edge(l, src)
                    l += 1
                if r & 1:
                    r -= 1
                    if forward: edge(src, r)
                    else: edge(r, src)
                l >>= 1
                r >>= 1
        # Segment tree downward edges to leaves
        for v in range(1, base):
            edge(N + v, N + 2*v)
            edge(N + v, N + 2*v + 1)
        # leaf tree nodes connect to town vertices
        for i in range(N):
            edge(N + base + i, i)
        # The graph above uses tree nodes offset by N; convert cover nodes
        # to the same offset by adapting the range builder.
        # (Rebuild cover edges correctly; remove direct-tree representation.)
        adj = [[] for _ in range(total)]
        radj = [[] for _ in range(total)]
        strict_edges = []
        def edge(a, b, strict=False):
            adj[a].append(b); radj[b].append(a)
            if strict: strict_edges.append((a,b))
        for v in range(1, base):
            edge(N+v, N+2*v); edge(N+v, N+2*v+1)
        for i in range(N):
            edge(N+base+i, i)
        def add_range(l, r, src, forward):
            l += base; r += base
            while l < r:
                if l & 1:
                    node = N+l
                    if forward: edge(src,node,True)
                    else: edge(node,src,True)
                    l += 1
                if r & 1:
                    r -= 1; node=N+r
                    if forward: edge(src,node,True)
                    else: edge(node,src,True)
                l >>= 1; r >>= 1
        for idx in range(L-1, R):
            l, r, increasing = people[idx]
            edge(l, r); edge(r, l)
            if increasing:
                # endpoint value is less than every interior town
                add_range(l+1, r, l, True)
            else:
                # every interior town is less than endpoint value
                add_range(l+1, r, l, False)
        # Kosaraju SCC; any strict edge within one SCC is contradictory.
        seen = bytearray(total)
        order = []
        for start in range(total):
            if seen[start]: continue
            stack = [(start, 0)]
            seen[start] = 1
            while stack:
                v, j = stack[-1]
                if j < len(adj[v]):
                    w = adj[v][j]
                    stack[-1] = (v, j+1)
                    if not seen[w]:
                        seen[w] = 1
                        stack.append((w, 0))
                else:
                    order.append(v); stack.pop()
        comp = [-1]*total
        cid = 0
        for start in reversed(order):
            if comp[start] != -1: continue
            comp[start] = cid
            stack = [start]
            while stack:
                v=stack.pop()
                for w in radj[v]:
                    if comp[w] == -1:
                        comp[w]=cid; stack.append(w)
